/* مولّد تلقائياً من panel/panel.html — لا تعدّله يدوياً (شغّل: python3 scripts/build_panel.py) */
export const PANEL_HTML = "<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>لوحة دليل السعودية</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css\">\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js\"></script>\n<style>\n.geo{position:relative}\n.geo .map{height:280px;border-radius:16px;margin-top:8px;border:1.5px solid var(--line);z-index:1}\n.sug{position:absolute;top:46px;right:0;left:0;background:#fff;border-radius:14px;box-shadow:0 10px 30px rgba(43,39,69,.18);z-index:5;overflow:hidden;display:none}\n.sug div{padding:10px 14px;cursor:pointer;border-bottom:1px solid var(--chip)}\n.sug div:hover{background:var(--chip)}\n.sug b{display:block;font-size:14px}.sug span{font-size:12px;color:var(--muted)}\n:root{--ink:#2B2745;--muted:#6B6585;--faint:#9C94B5;--purple:#604C87;--lilac:#8E65AB;--orange:#F89743;--orangeDeep:#E07B22;--pink:#EB839B;--pinkDeep:#C9506F;--sky:#62B9E8;--skyDeep:#2E86B8;--green:#3E8E5A;--bg:#F4F1EE;--line:#E2DAEC;--chip:#F1ECF6;--white:#fff;--softPurple:#ECE5F3;--softOrange:#FDE7D3;--softPink:#FBE3EA;--softGreen:#E2F0E6;--softSky:#E2F1FA}\n*{box-sizing:border-box}\nbody{margin:0;font-family:'IBM Plex Sans Arabic',system-ui,sans-serif;background:var(--bg);color:var(--ink);font-size:15px}\nbutton,input,select,textarea{font:inherit;color:inherit}\na{color:var(--purple)}\n.app{display:flex;min-height:100vh}\naside{width:230px;background:var(--ink);color:#fff;padding:22px 14px;position:sticky;top:0;height:100vh;flex-shrink:0;display:flex;flex-direction:column;gap:4px}\n.brand{display:flex;align-items:center;gap:10px;padding:0 8px 18px;font-weight:700;font-size:17px}\n.brand i{width:36px;height:36px;border-radius:11px;background:var(--orange);display:grid;place-items:center;font-style:normal}\n.nav{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:12px;cursor:pointer;color:#CFC6DE;font-weight:600;border:0;background:none;text-align:right;width:100%}\n.nav:hover{background:rgba(255,255,255,.07)}\n.nav.on{background:var(--orange);color:#fff}\n.nav b{margin-inline-start:auto;background:var(--pinkDeep);color:#fff;border-radius:999px;padding:0 8px;font-size:12px}\naside .foot{margin-top:auto;font-size:12px;color:#9C94B5;padding:8px}\nmain{flex:1;min-width:0;padding:26px 28px 80px}\nh1{font-size:26px;margin:0 0 4px}\n.sub{color:var(--muted);margin:0 0 20px}\n.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.grow{flex:1}\n.stats{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:20px}\n.stat{background:#fff;border-radius:20px;padding:16px}\n.stat .n{font-size:28px;font-weight:700}\n.stat .l{color:var(--muted);font-size:13px}\n.card{background:#fff;border-radius:20px;padding:16px}\n.btn{border:0;border-radius:12px;padding:9px 16px;font-weight:700;cursor:pointer;background:var(--purple);color:#fff;white-space:nowrap}\n.btn.o{background:var(--orange)}.btn.g{background:var(--green)}.btn.p{background:var(--pinkDeep)}\n.btn.ghost{background:var(--chip);color:var(--ink)}\n.btn:disabled{opacity:.5;cursor:default}\n.in,select.in,textarea.in{background:#fff;border:1.5px solid var(--line);border-radius:12px;padding:9px 12px;width:100%;outline:none}\n.in:focus{border-color:var(--lilac)}\ntextarea.in{min-height:130px;resize:vertical;line-height:1.8}\n.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}\n.filters .in{width:auto;min-width:150px}\n.list{display:grid;gap:10px}\n.item{display:flex;gap:12px;align-items:center;background:#fff;border-radius:18px;padding:10px;cursor:pointer;border:2px solid transparent}\n.item:hover{border-color:var(--line)}\n.item img,.item .ph{width:64px;height:64px;border-radius:14px;object-fit:cover;background:var(--chip);flex-shrink:0;display:grid;place-items:center;color:var(--faint);font-size:12px}\n.item .t{font-weight:700}\n.item .m{color:var(--muted);font-size:13px}\n.badge{display:inline-block;border-radius:999px;padding:2px 10px;font-size:12px;font-weight:700}\n.b-live{background:var(--softGreen);color:var(--green)}.b-draft{background:var(--softOrange);color:var(--orangeDeep)}.b-hidden{background:var(--chip);color:var(--muted)}\n.b-panel{background:var(--softPurple);color:var(--purple)}\n.tabs{display:flex;gap:6px;background:#fff;border-radius:14px;padding:4px;width:fit-content;margin-bottom:14px}\n.tabs button{border:0;background:none;padding:7px 14px;border-radius:10px;font-weight:700;cursor:pointer;color:var(--muted)}\n.tabs button.on{background:var(--purple);color:#fff}\n.drawer{position:fixed;inset:0;background:rgba(43,39,69,.45);display:none;z-index:20}\n.drawer.on{display:block}\n.sheet{position:absolute;top:0;bottom:0;left:0;width:min(720px,100%);background:var(--bg);overflow:auto;padding:22px 24px 120px;box-shadow:0 0 40px rgba(0,0,0,.2)}\n.sheet h2{margin:0;font-size:22px}\n.f{display:grid;gap:6px;margin-top:14px}\n.f label{font-weight:700;font-size:13px}\n.f small{color:var(--muted);font-size:12px}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.chips{display:flex;gap:6px;flex-wrap:wrap}\n.chip{border:1.5px solid var(--line);background:#fff;border-radius:999px;padding:4px 12px;cursor:pointer;font-size:13px;font-weight:600}\n.chip.on{background:var(--purple);border-color:var(--purple);color:#fff}\n.imgs{display:flex;gap:8px;flex-wrap:wrap}\n.imgs .im{position:relative;width:110px;height:84px;border-radius:12px;overflow:hidden;background:var(--chip)}\n.imgs .im img{width:100%;height:100%;object-fit:cover}\n.imgs .im .x{position:absolute;top:4px;left:4px;width:24px;height:24px;border-radius:12px;background:rgba(0,0,0,.6);color:#fff;border:0;cursor:pointer}\n.imgs .im .cover{position:absolute;bottom:4px;right:4px;background:var(--orange);color:#fff;font-size:11px;border-radius:999px;padding:0 8px;font-weight:700}\n.imgs .im .mk{position:absolute;bottom:4px;right:4px;background:rgba(255,255,255,.85);border:0;border-radius:999px;font-size:11px;padding:0 8px;cursor:pointer}\n.up{font:inherit;line-height:1.5;width:110px;height:84px;border-radius:12px;border:2px dashed var(--line);display:grid;place-items:center;cursor:pointer;color:var(--muted);font-size:13px;background:#fff}\n.bar{position:sticky;bottom:-120px;margin:22px -24px -120px;padding:14px 24px 24px;background:linear-gradient(transparent,var(--bg) 30%);display:flex;gap:8px;flex-wrap:wrap}\n.im[draggable=true]{cursor:grab}.im.dragging{opacity:.4}.im.over{outline:3px solid var(--orange)}\n.warn{background:var(--softOrange);color:var(--orangeInk,#995306);border-radius:14px;padding:10px 14px;font-size:13px;margin-top:10px}\n.warn a{color:inherit;font-weight:700}\n.prev{background:#fff;border-radius:22px;overflow:hidden;max-width:340px;box-shadow:0 8px 30px rgba(43,39,69,.12);margin-top:10px}\n.prev .cv{height:170px;background:var(--chip) center/cover;position:relative}\n.prev .cv b{position:absolute;bottom:10px;right:10px;background:#fff;border-radius:999px;padding:2px 10px;font-size:12px}\n.prev .bd{padding:14px}.prev h3{margin:0;font-size:19px}.prev p{margin:6px 0 0;color:var(--muted);font-size:13px;line-height:1.8}\n.mini{border:0;border-radius:10px;padding:5px 12px;font-weight:700;cursor:pointer;font-size:13px}\n.season{background:#fff;border-radius:20px;padding:16px;cursor:pointer;border-right:6px solid var(--purple)}\n.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:var(--ink);color:#fff;padding:10px 18px;border-radius:14px;font-weight:600;z-index:50;display:none}\n.empty{color:var(--muted);text-align:center;padding:40px}\n.login{max-width:380px;margin:12vh auto;background:#fff;border-radius:26px;padding:28px;text-align:center}\n.login i{display:inline-grid;place-items:center;width:64px;height:64px;border-radius:20px;background:var(--purple);color:#fff;font-style:normal;font-size:28px;margin-bottom:10px}\n.post{background:#fff;border-radius:18px;padding:14px;display:grid;gap:8px}\n.muted{color:var(--muted)}\n.tag{font-size:12px;color:var(--skyDeep);font-weight:700}\n.hint{background:var(--softPurple);border-radius:14px;padding:10px 14px;font-size:13px;color:var(--purple)}\n@media (max-width:820px){\n  .app{flex-direction:column}\n  aside{width:auto;height:auto;position:sticky;top:0;z-index:10;flex-direction:row;overflow-x:auto;padding:10px;gap:4px}\n  .brand,aside .foot{display:none}\n  .nav{width:auto;white-space:nowrap;padding:8px 12px}\n  main{padding:18px 16px 80px}\n  .two{grid-template-columns:1fr}\n  .sheet{padding:18px 16px 120px}\n  .bar{margin:22px -16px -120px;padding:14px 16px 24px}\n}\n</style>\n</head>\n<body>\n<div id=\"root\"></div>\n<div class=\"toast\" id=\"toast\"></div>\n<script>\nconst API = location.origin;\nconst KIND = { islamic: 'معالم إسلامية', heritage: 'تراث وثقافة', nature: 'طبيعة', sights: 'معالم سياحية', fun: 'ترفيه', food: 'مطاعم', cafe: 'مقاهي', shopping: 'تسوق' };\nconst ST = { live: ['منشور', 'b-live'], draft: ['مسودة', 'b-draft'], hidden: ['مخفي', 'b-hidden'] };\nconst EV_TYPES = ['حفلات غنائية', 'مسرح', 'رياضية', 'مهرجانات', 'معارض ومؤتمرات', 'تراث وثقافة', 'ترفيه', 'تجارب ومغامرات', 'عائلية', 'طعام'];\nconst SEASONS = ['موسم الرياض', 'موسم جدة', 'موسم الدرعية', 'لحظات العلا'];\nlet KEY = localStorage.getItem('sg_admin') || '';\nlet META = null, VIEW = 'home', SUMMARY = null;\nconst $ = (s, el = document) => el.querySelector(s);\nconst h = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst cityName = (id) => META?.cities.find((c) => c.id === id)?.name || id || '—';\nfunction toast(t) { const el = $('#toast'); el.textContent = t; el.style.display = 'block'; clearTimeout(toast.t); toast.t = setTimeout(() => (el.style.display = 'none'), 2600); }\n\nasync function api(path, opt = {}) {\n  const r = await fetch(API + path, { method: opt.method || 'GET', headers: { 'X-Admin-Key': KEY, ...(opt.body && !(opt.body instanceof Blob) ? { 'Content-Type': 'application/json' } : {}), ...(opt.headers || {}) }, body: opt.body instanceof Blob ? opt.body : opt.body ? JSON.stringify(opt.body) : undefined });\n  const d = await r.json().catch(() => ({}));\n  if (r.status === 401) { const wasIn = !!localStorage.getItem('sg_admin'); KEY = ''; localStorage.removeItem('sg_admin'); if (wasIn) render(); throw new Error('unauthorized'); }\n  if (!r.ok) throw new Error(d.error || 'http_' + r.status);\n  return d;\n}\nconst ERR = { text_required: 'اكتب الرسالة', title_required: 'اكتب الاسم', start_required: 'حدد تاريخ البداية', bad_city: 'اختر المدينة', bad_type: 'الصورة لازم JPG أو PNG أو WEBP', bad_size: 'الصورة أكبر من 10MB' };\nconst errMsg = (e) => ERR[e.message] || 'صار خطأ: ' + e.message;\n\n/* ——— الدخول ——— */\nfunction loginView() {\n  $('#root').innerHTML = `<div class=\"login\"><i>د</i><h1 style=\"font-size:22px\">لوحة دليل السعودية</h1>\n    <p class=\"sub\">اضغط الزر البرتقالي عشان يلصق مفتاح الإدارة اللي نسخه لك أمر «افتح-اللوحة».</p>\n    <button class=\"btn o\" style=\"width:100%;padding:14px;font-size:17px\" id=\"paste\">الصق المفتاح وادخل</button>\n    <p class=\"muted\" style=\"margin:16px 0 8px;font-size:13px\">أو الصقه يدوياً هنا (Cmd+V):</p>\n    <input class=\"in\" id=\"k\" type=\"password\" placeholder=\"مفتاح الإدارة\" autocomplete=\"off\" autofocus>\n    <button class=\"btn\" style=\"width:100%;margin-top:10px\" id=\"go\">دخول</button><p id=\"msg\" style=\"color:var(--pinkDeep);font-weight:700\"></p></div>`;\n  const go = async (k) => {\n    const raw = String(k || $('#k').value);\n    // المفتاح حروف وأرقام إنجليزية بس — نطلعه حتى لو انلصق معه كلام ثاني\n    KEY = (raw.match(/[A-Za-z0-9_-]{8,}/) || [''])[0];\n    if (!raw.trim()) { $('#msg').textContent = 'ما فيه شي منسوخ. شغّل أمر «افتح-اللوحة» مرة ثانية، وبعده لا تنسخ أي شي ثاني'; return; }\n    if (!KEY) { $('#msg').textContent = 'اللي منسوخ مو المفتاح (غالباً نسخت شي بعد الأمر). شغّل أمر «افتح-اللوحة» مرة ثانية، وبعده اضغط الزر البرتقالي على طول'; return; }\n    try { await api('/admin/summary'); localStorage.setItem('sg_admin', KEY); render(); }\n    catch (e) { KEY = ''; $('#msg').textContent = e.message === 'unauthorized' ? 'المفتاح غلط. شغّل أمر «افتح-اللوحة» مرة ثانية' : 'السيرفر ما رد: ' + e.message; }\n  };\n  $('#paste').onclick = async () => {\n    try { const t = await navigator.clipboard.readText(); go(t); }\n    catch { $('#msg').textContent = 'المتصفح ما سمح باللصق. اضغط داخل الخانة تحت واضغط Cmd+V'; $('#k').focus(); }\n  };\n  $('#go').onclick = () => go(); $('#k').onkeydown = (e) => { if (e.key === 'Enter') go(); };\n  setTimeout(() => $('#k').focus(), 100);\n}\n\n/* ——— الهيكل ——— */\nconst NAV = [['home', 'الرئيسية'], ['places', 'الأماكن'], ['events', 'الفعاليات'], ['seasons', 'المواسم'], ['weekly', 'مختارات الأسبوع'], ['articles', 'الأخبار'], ['community', 'المجتمع'], ['users', 'المستخدمين']];\nasync function render() {\n  if (!KEY) return loginView();\n  if (!META) { try { META = await api('/admin/meta'); } catch (e) { if (KEY) $('#root').innerHTML = `<div class=\"login\"><p>ما قدرنا نحمّل اللوحة (${h(e.message)}). حدّث الصفحة.</p></div>`; return; } }\n  const rep = SUMMARY?.counts?.reported || 0;\n  $('#root').innerHTML = `<div class=\"app\"><aside><div class=\"brand\"><i>د</i>لوحة الدليل</div>\n    ${NAV.map(([id, t]) => `<button class=\"nav ${VIEW === id ? 'on' : ''}\" data-v=\"${id}\">${t}${id === 'community' && rep ? `<b>${rep}</b>` : ''}</button>`).join('')}\n    <div class=\"foot\">كل وقت بتوقيت مكة<br><a href=\"#\" id=\"out\" style=\"color:#CFC6DE\">خروج</a></div></aside><main id=\"main\"></main></div>`;\n  document.querySelectorAll('.nav').forEach((b) => (b.onclick = () => { VIEW = b.dataset.v; render(); }));\n  $('#out').onclick = (e) => { e.preventDefault(); KEY = ''; localStorage.removeItem('sg_admin'); render(); };\n  ({ home: homeView, places: placesView, events: eventsView, seasons: seasonsView, weekly: weeklyView, articles: articlesView, community: communityView, users: usersView })[VIEW]();\n}\n\n/* ——— الرئيسية ——— */\nasync function homeView() {\n  const m = $('#main');\n  m.innerHTML = '<p class=\"muted\">لحظة...</p>';\n  SUMMARY = await api('/admin/summary');\n  const c = SUMMARY.counts;\n  const S = (n, l, color, go) => `<div class=\"stat\" ${go ? `data-go=\"${go}\" style=\"cursor:pointer\"` : ''}><div class=\"n\" style=\"color:${color}\">${n}</div><div class=\"l\">${l}</div></div>`;\n  m.innerHTML = `<h1>أهلاً رامي</h1><p class=\"sub\">هذي لوحتك: أي شي تضيفه أو تعدّله هنا يوصل للتطبيق خلال دقائق.</p>\n    <div class=\"row\" style=\"margin-bottom:18px\"><button class=\"btn o\" id=\"addP\">+ مكان جديد</button><button class=\"btn\" id=\"addE\">+ فعالية جديدة</button></div>\n    <div class=\"stats\">${S(c.places, 'مكان منشور', 'var(--purple)', 'places')}${S(c.drafts, 'مسودة تنتظر النشر', 'var(--orangeDeep)', 'drafts')}${S(c.events, 'فعالية قادمة', 'var(--skyDeep)', 'events')}\n    ${S(c.reported, 'بلاغ يحتاج مراجعة', 'var(--pinkDeep)', 'community')}${S(c.users, 'مستخدم مسجّل', 'var(--green)', 'users')}${S(c.posts + ' / ' + c.answers, 'سؤال / إجابة', 'var(--lilac)', 'community')}\n    ${S(c.noPhoto, 'مكان بدون صورة', 'var(--muted)', 'nophoto')}${S(c.noGeo, 'مكان بدون موقع', 'var(--muted)', 'nogeo')}</div>\n    <div class=\"card\"><b>آخر مشاركات المجتمع</b><div class=\"list\" style=\"margin-top:10px\">${SUMMARY.recent.map((r) => `<div class=\"m\">${h(r.name || 'مستخدم')} · ${h(r.text.slice(0, 90))}</div>`).join('') || '<div class=\"muted\">ما فيه مشاركات للحين</div>'}</div></div>`;\n  $('#addP').onclick = () => editPlace(null);\n  $('#addE').onclick = () => editEvent(null);\n  m.querySelectorAll('[data-go]').forEach((el) => (el.onclick = () => {\n    const g = el.dataset.go;\n    if (g === 'drafts') { PF.status = 'draft'; VIEW = 'places'; } else if (g === 'nophoto') { PF.missing = 'photo'; VIEW = 'places'; } else if (g === 'nogeo') { PF.missing = 'geo'; VIEW = 'places'; } else VIEW = g;\n    render();\n  }));\n}\n\n/* ——— الأماكن ——— */\nconst PF = { city: '', status: '', q: '', missing: '', page: 1 };\nasync function placesView() {\n  const m = $('#main');\n  m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>الأماكن</h1><p class=\"sub\">الأماكن الجديدة تنحفظ مسودة، وما تظهر في التطبيق لين تضغط «انشر».</p></div><button class=\"btn o\" id=\"add\">+ مكان جديد</button></div>\n    <div class=\"filters\"><input class=\"in\" id=\"q\" placeholder=\"ابحث بالاسم أو الرقم\" value=\"${h(PF.q)}\">\n    <select class=\"in\" id=\"city\"><option value=\"\">كل المدن</option>${META.cities.map((c) => `<option value=\"${c.id}\" ${PF.city === c.id ? 'selected' : ''}>${c.name}</option>`).join('')}</select>\n    <select class=\"in\" id=\"status\"><option value=\"\">كل الحالات</option>${Object.entries(ST).map(([k, v]) => `<option value=\"${k}\" ${PF.status === k ? 'selected' : ''}>${v[0]}</option>`).join('')}</select>\n    <select class=\"in\" id=\"missing\"><option value=\"\">بدون فلتر</option><option value=\"photo\" ${PF.missing === 'photo' ? 'selected' : ''}>بدون صورة</option><option value=\"geo\" ${PF.missing === 'geo' ? 'selected' : ''}>بدون موقع</option></select></div>\n    <div id=\"res\" class=\"list\"><p class=\"muted\">لحظة...</p></div>`;\n  $('#add').onclick = () => editPlace(null);\n  let t; $('#q').oninput = (e) => { clearTimeout(t); t = setTimeout(() => { PF.q = e.target.value; PF.page = 1; loadPlaces(); }, 350); };\n  ['city', 'status', 'missing'].forEach((k) => ($('#' + k).onchange = (e) => { PF[k] = e.target.value; PF.page = 1; loadPlaces(); }));\n  loadPlaces();\n}\nasync function loadPlaces() {\n  const qs = new URLSearchParams(Object.entries(PF).filter(([, v]) => v)).toString();\n  const d = await api('/admin/places?' + qs);\n  const pages = Math.ceil(d.total / 30);\n  $('#res').innerHTML = `<div class=\"muted\" style=\"font-size:13px\">${d.total} مكان</div>` + (d.places.map((p) => `<div class=\"item\" data-id=\"${p.id}\">\n    ${p.thumb ? `<img src=\"${h(p.thumb)}\" loading=\"lazy\">` : '<div class=\"ph\">بدون صورة</div>'}\n    <div class=\"grow\"><div class=\"t\">${h(p.title)}</div><div class=\"m\">${cityName(p.city)} · ${p.kinds.map((k) => KIND[k] || k).join('، ') || 'بدون تصنيف'}${!p.lat ? ' · <span style=\"color:var(--pinkDeep)\">بدون موقع</span>' : ''}</div></div>\n    ${p.status === 'draft' ? `<button class=\"mini\" style=\"background:var(--softGreen);color:var(--green)\" data-pub=\"${p.id}\">انشر</button>` : ''}<span class=\"badge ${ST[p.status][1]}\">${ST[p.status][0]}</span></div>`).join('') || '<div class=\"empty\">ما فيه نتائج</div>')\n    + (pages > 1 ? `<div class=\"row\" style=\"justify-content:center;margin-top:10px\">${PF.page > 1 ? '<button class=\"btn ghost\" id=\"prev\">السابق</button>' : ''}<span class=\"muted\">${PF.page} من ${pages}</span>${PF.page < pages ? '<button class=\"btn ghost\" id=\"next\">التالي</button>' : ''}</div>` : '');\n  document.querySelectorAll('#res .item').forEach((el) => (el.onclick = async () => editPlace((await api('/admin/places/' + el.dataset.id)).place)));\n  document.querySelectorAll('#res [data-pub]').forEach((b) => (b.onclick = async (e) => { e.stopPropagation(); await api(`/admin/places/${b.dataset.pub}/status`, { method: 'POST', body: { status: 'live' } }); toast('انتشر'); loadPlaces(); }));\n  $('#prev') && ($('#prev').onclick = () => { PF.page--; loadPlaces(); });\n  $('#next') && ($('#next').onclick = () => { PF.page++; loadPlaces(); });\n}\n\n/* ——— أدوات النماذج ——— */\nfunction drawer(html) {\n  let d = $('#drawer');\n  if (!d) { d = document.createElement('div'); d.id = 'drawer'; d.className = 'drawer'; document.body.appendChild(d); d.onclick = (e) => { if (e.target === d) closeDrawer(); }; }\n  d.innerHTML = `<div class=\"sheet\">${html}</div>`; d.classList.add('on'); return d;\n}\nconst closeDrawer = () => $('#drawer')?.classList.remove('on');\nfunction imagesWidget(el, list, onChange) {\n  const draw = () => {\n    el.innerHTML = `<div class=\"imgs\">${list.map((u, i) => `<div class=\"im\" draggable=\"true\" data-i=\"${i}\" title=\"اسحبها لترتيب الصور\"><img src=\"${h(u)}\" draggable=\"false\">${i === 0 ? '<span class=\"cover\">الغلاف</span>' : `<button class=\"mk\" data-i=\"${i}\">اجعلها الغلاف</button>`}<button class=\"x\" data-i=\"${i}\" title=\"شيل\">×</button></div>`).join('')}\n      <button type=\"button\" class=\"up\" id=\"upBtn\">+ صورة<br><small>أو اسحبها هنا</small></button><input type=\"file\" accept=\"image/*\" multiple style=\"position:absolute;width:1px;height:1px;opacity:0;pointer-events:none\"></div>\n      <input class=\"in\" style=\"margin-top:8px\" placeholder=\"أو الصق رابط صورة واضغط Enter\">`;\n    el.querySelectorAll('.x').forEach((b) => (b.onclick = () => { list.splice(+b.dataset.i, 1); draw(); }));\n    let from = -1;\n    el.querySelectorAll('.im').forEach((im) => {\n      im.ondragstart = (e) => { from = +im.dataset.i; im.classList.add('dragging'); e.dataTransfer.effectAllowed = 'move'; e.dataTransfer.setData('text/plain', 'img'); };\n      im.ondragend = () => im.classList.remove('dragging');\n      im.ondragover = (e) => { if (from < 0) return; e.preventDefault(); e.stopPropagation(); im.classList.add('over'); };\n      im.ondragleave = () => im.classList.remove('over');\n      im.ondrop = (e) => { if (from < 0) return; e.preventDefault(); e.stopPropagation(); const to = +im.dataset.i; const [u] = list.splice(from, 1); list.splice(to, 0, u); from = -1; draw(); onChange && onChange(); };\n    });\n    el.querySelectorAll('.mk').forEach((b) => (b.onclick = () => { const [u] = list.splice(+b.dataset.i, 1); list.unshift(u); draw(); onChange && onChange(); }));\n    const fi = el.querySelector('input[type=file]');\n    el.querySelector('#upBtn').onclick = () => fi.click();\n    const upload = async (files) => {\n      for (const f of files) {\n        if (!/^image\\/(jpeg|png|webp)$/.test(f.type)) { toast('الصورة لازم JPG أو PNG أو WEBP (صور الآيفون HEIC حوّلها أول)'); continue; }\n        toast('يرفع الصورة...');\n        try { const r = await api('/admin/upload', { method: 'POST', body: f, headers: { 'Content-Type': f.type } }); list.push(r.url); draw(); onChange && onChange(); toast('انرفعت'); } catch (er) { toast(errMsg(er)); }\n      }\n    };\n    fi.onchange = (e) => upload([...e.target.files]);\n    const zone = el.querySelector('.imgs');\n    zone.ondragover = (e) => { e.preventDefault(); zone.style.outline = '2px dashed var(--orange)'; };\n    zone.ondragleave = () => (zone.style.outline = '');\n    zone.ondrop = (e) => { e.preventDefault(); zone.style.outline = ''; if (e.dataTransfer.files.length) upload([...e.dataTransfer.files]); };\n    el.querySelector('input.in').onkeydown = (e) => { if (e.key === 'Enter' && /^https?:\\/\\//.test(e.target.value)) { e.preventDefault(); list.push(e.target.value.trim()); draw(); } };\n  };\n  draw();\n}\nfunction chipsWidget(el, options, selected, allowNew) {\n  const all = [...new Set([...options, ...selected])];\n  const draw = () => {\n    el.innerHTML = `<div class=\"chips\">${all.map((o) => `<span class=\"chip ${selected.includes(o) ? 'on' : ''}\" data-o=\"${h(o)}\">${h(o)}</span>`).join('')}</div>${allowNew ? '<input class=\"in\" style=\"margin-top:8px\" placeholder=\"تصنيف جديد؟ اكتبه واضغط Enter\">' : ''}`;\n    el.querySelectorAll('.chip').forEach((c) => (c.onclick = () => { const o = c.dataset.o; const i = selected.indexOf(o); i >= 0 ? selected.splice(i, 1) : selected.push(o); draw(); }));\n    const inp = el.querySelector('input'); if (inp) inp.onkeydown = (e) => { if (e.key === 'Enter' && e.target.value.trim()) { e.preventDefault(); const v = e.target.value.trim(); all.push(v); selected.push(v); draw(); } };\n  };\n  draw();\n}\n/** يطلع الإحداثيات من رابط قوقل ماب أو من «24.46, 39.61» */\nfunction parseGeo(s) {\n  const m = String(s).match(/@(-?\\d+\\.\\d+),(-?\\d+\\.\\d+)/) || String(s).match(/[?&]q=(-?\\d+\\.\\d+),(-?\\d+\\.\\d+)/) || String(s).match(/!3d(-?\\d+\\.\\d+)!4d(-?\\d+\\.\\d+)/) || String(s).match(/^\\s*(-?\\d+\\.\\d+)\\s*[,،]\\s*(-?\\d+\\.\\d+)\\s*$/);\n  return m ? [+m[1], +m[2]] : null;\n}\n/** الموقع: بحث بالاسم (OpenStreetMap) + خريطة بدبوس تسحبه + لصق رابط قوقل ماب */\nfunction geoWidget(box, lat, lng, cityFn, addrEl, onSet) {\n  box.innerHTML = `<div class=\"geo\"><input class=\"in\" id=\"gq\" placeholder=\"اكتب اسم المكان... أو الصق رابط قوقل ماب\" autocomplete=\"off\"><div class=\"sug\" id=\"sug\"></div>\n    <input type=\"hidden\" id=\"geo\" value=\"${lat ? lat + ', ' + lng : ''}\"><div class=\"map\" id=\"gmap\"></div><small id=\"geoMsg\" class=\"muted\"></small></div>`;\n  const q = $('#gq', box), sug = $('#sug', box), out = $('#geo', box), msg = $('#geoMsg', box);\n  const center = () => { const c = META.cities.find((x) => x.id === cityFn()); return c ? [c.lat, c.lng] : [24.2, 44.5]; };\n  if (!window.L) { $('#gmap', box).remove(); window.L = { map: () => ({ setView() { return this; }, on() {}, invalidateSize() {}, addLayer() {}, removeLayer() {} }), tileLayer: () => ({ addTo() { return this; }, on() {} }), marker: () => ({ addTo() { return this; }, on() {}, setLatLng() {} }) }; }\n  const map = L.map($('#gmap', box), { zoomControl: true, attributionControl: true }).setView(lat ? [lat, lng] : center(), lat ? 16 : (cityFn() ? 11 : 5));\n  // خريطة OpenStreetMap، ولو رفضت نحوّل تلقائياً لخرائط Esri\n  let fails = 0, alt = false;\n  const osm = L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '© OpenStreetMap' }).addTo(map);\n  osm.on && osm.on('tileerror', () => { if (++fails > 2 && !alt) { alt = true; map.removeLayer(osm); L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', { maxZoom: 19, attribution: 'Tiles © Esri' }).addTo(map); } });\n  let pin = null;\n  const set = (la, ln, zoom) => {\n    la = +(+la).toFixed(6); ln = +(+ln).toFixed(6);\n    out.value = la + ', ' + ln;\n    if (!pin) { pin = L.marker([la, ln], { draggable: true }).addTo(map); pin.on('dragend', () => { const p = pin.getLatLng(); set(p.lat, p.lng); }); } else pin.setLatLng([la, ln]);\n    if (zoom) map.setView([la, ln], zoom);\n    msg.innerHTML = `✓ ${la}, ${ln} · <a target=\"_blank\" href=\"https://maps.google.com/?q=${la},${ln}\">تأكد في قوقل ماب</a> · تقدر تسحب الدبوس لو مو مضبوط`;\n    onSet && onSet(la, ln);\n  };\n  if (lat) set(lat, lng); else msg.textContent = 'اكتب الاسم واختر من القائمة، أو اضغط على الخريطة مكان المكان';\n  setTimeout(() => map.invalidateSize(), 250);\n  map.on('click', (ev) => set(ev.latlng.lat, ev.latlng.lng));\n  let t, last = '';\n  q.oninput = () => {\n    const v = q.value.trim();\n    const g = parseGeo(v);\n    if (g) { sug.style.display = 'none'; set(g[0], g[1], 17); return; }\n    if (/^https?:\\/\\//.test(v)) { sug.style.display = 'none'; msg.innerHTML = '<span style=\"color:var(--pinkDeep)\">ما قدرت أقرا الرابط. الروابط المختصرة (maps.app.goo.gl) افتحها بالمتصفح أول وانسخ الرابط الطويل، أو اكتب اسم المكان.</span>'; return; }\n    clearTimeout(t);\n    if (v.length < 3) { sug.style.display = 'none'; return; }\n    t = setTimeout(async () => {\n      if (v === last) return; last = v;\n      const c = center(), b = 1.2;\n      const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&limit=6&countrycodes=sa&accept-language=ar&q=${encodeURIComponent(v)}` + (cityFn() ? `&viewbox=${c[1] - b},${c[0] + b},${c[1] + b},${c[0] - b}` : '');\n      try {\n        const r = await fetch(url).then((x) => x.json());\n        sug.innerHTML = r.length ? r.map((x, i) => `<div data-i=\"${i}\"><b>${h(x.name || x.display_name.split('،')[0].split(',')[0])}</b><span>${h(x.display_name)}</span></div>`).join('') : '<div style=\"cursor:default\"><span>ما لقيت شي. جرّب اسم ثاني، أو اضغط على الخريطة مكان المكان.</span></div>';\n        sug.style.display = 'block';\n        sug.querySelectorAll('[data-i]').forEach((el) => (el.onclick = () => {\n          const x = r[+el.dataset.i]; sug.style.display = 'none'; q.value = x.name || '';\n          set(x.lat, x.lon, 17);\n          if (addrEl && !addrEl.value) addrEl.value = x.display_name.split(/[،,]/).slice(0, 3).join('،').trim();\n        }));\n      } catch { msg.textContent = 'البحث ما اشتغل الحين. اضغط على الخريطة مكان المكان.'; }\n    }, 600);\n  };\n  q.onblur = () => setTimeout(() => (sug.style.display = 'none'), 200);\n}\nconst plainBody = (html) => String(html || '').replace(/<br\\s*\\/?>/gi, '\\n').replace(/<\\/p>\\s*<p[^>]*>/gi, '\\n\\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').trim();\n\n/* ——— محرّر المكان ——— */\nfunction editPlace(p) {\n  const isNew = !p;\n  p = p || { city: PF.city || '', title: '', title_en: '', cats: [], kinds: [], summary: '', body: '', images: [], lat: null, lng: null, address: '', phone: '', website: '', email: '', status: 'draft' };\n  const images = [...p.images], cats = [...p.cats], kinds = [...p.kinds];\n  const d = drawer(`<div class=\"row\"><div class=\"grow\"><h2>${isNew ? 'مكان جديد' : h(p.title)}</h2><div class=\"m muted\">${isNew ? 'بينحفظ مسودة' : `رقم ${p.id} · <span class=\"badge ${ST[p.status][1]}\">${ST[p.status][0]}</span>${p.fromPanel ? ' <span class=\"badge b-panel\">معدّل من اللوحة</span>' : ''}`}</div></div><button class=\"btn ghost\" id=\"x\">إغلاق</button></div>\n    <div id=\"prevBox\" style=\"display:none\"></div>\n    <div class=\"two\"><div class=\"f\"><label>الاسم بالعربي *</label><input class=\"in\" id=\"title\" value=\"${h(p.title)}\"></div><div class=\"f\"><label>الاسم بالإنجليزي</label><input class=\"in\" id=\"title_en\" value=\"${h(p.title_en)}\" dir=\"ltr\"></div></div>\n    <div id=\"dup\"></div>\n    <div class=\"f\"><label>المدينة *</label><select class=\"in\" id=\"city\"><option value=\"\">اختر</option>${META.cities.map((c) => `<option value=\"${c.id}\" ${p.city === c.id ? 'selected' : ''}>${c.name}</option>`).join('')}</select></div>\n    <div class=\"f\"><label>النوع في التطبيق</label><div id=\"kinds\"></div><small>يحدد لون وأيقونة المكان في الخريطة والفلاتر</small></div>\n    <div class=\"f\"><label>التصنيفات</label><div id=\"cats\"></div></div>\n    <div class=\"f\"><label>الصور</label><div id=\"imgs\"></div><small>أول صورة هي الغلاف</small></div>\n    <div class=\"f\"><label>وصف قصير</label><input class=\"in\" id=\"summary\" value=\"${h(p.summary)}\" maxlength=\"400\"><small>يطلع في القوائم ونتائج البحث</small></div>\n    <div class=\"f\"><label>عن المكان</label><textarea class=\"in\" id=\"body\">${h(plainBody(p.body))}</textarea><small>سطر فاضي بين الفقرات</small></div>\n    <div class=\"f\"><label>الموقع على الخريطة</label><div id=\"geoBox\"></div></div>\n    <div class=\"f\"><label>العنوان</label><input class=\"in\" id=\"address\" value=\"${h(p.address)}\"></div>\n    <div class=\"two\"><div class=\"f\"><label>الجوال</label><input class=\"in\" id=\"phone\" value=\"${h(p.phone)}\" dir=\"ltr\"></div><div class=\"f\"><label>الموقع الإلكتروني</label><input class=\"in\" id=\"website\" value=\"${h(p.website)}\" dir=\"ltr\"></div></div>\n    <div class=\"bar\"><button class=\"btn\" id=\"save\">حفظ</button>\n      ${p.status !== 'live' ? '<button class=\"btn g\" id=\"pub\">حفظ وانشر</button>' : '<button class=\"btn ghost\" id=\"unpub\">رجّعه مسودة</button>'}\n      ${!isNew && p.status !== 'hidden' ? '<button class=\"btn ghost\" id=\"hide\" style=\"color:var(--pinkDeep)\">إخفاء</button>' : ''}<button class=\"btn ghost\" id=\"pv\">معاينة في التطبيق</button></div>`);\n  /* معاينة: شكل بطاقة المكان في التطبيق */\n  const drawPrev = () => {\n    const box = $('#prevBox', d); if (box.style.display === 'none') return;\n    const c = collect();\n    box.innerHTML = `<div class=\"hint\">هذا شكل المكان تقريباً في التطبيق</div><div class=\"prev\"><div class=\"cv\" style=\"background-image:url('${h(images[0] || '')}')\">${c.kinds[0] ? `<b>${KIND[c.kinds[0]]}</b>` : ''}</div>\n      <div class=\"bd\"><h3>${h(c.title || 'اسم المكان')}</h3><div class=\"muted\" style=\"font-size:13px\">${cityName(c.city)}${c.lat ? ' · على الخريطة ✓' : ' · <span style=\"color:var(--pinkDeep)\">بدون موقع</span>'}</div>\n      <p>${h(c.summary || 'الوصف القصير يطلع هنا')}</p><p>${h(plainBody(c.body).slice(0, 220))}${plainBody(c.body).length > 220 ? '…' : ''}</p>\n      ${images.length > 1 ? `<p>${images.length} صور</p>` : ''}</div></div>`;\n  };\n  $('#pv', d).onclick = () => { const box = $('#prevBox', d); box.style.display = box.style.display === 'none' ? 'block' : 'none'; drawPrev(); if (box.style.display === 'block') d.querySelector('.sheet').scrollTo({ top: 0, behavior: 'smooth' }); };\n  d.querySelector('.sheet').addEventListener('input', () => drawPrev());\n  /* تنبيه التكرار */\n  let dupT;\n  const checkDup = () => { clearTimeout(dupT); dupT = setTimeout(async () => {\n    const c = collect(); if (!c.title && !c.lat) return;\n    const r = await api('/admin/places/similar?' + new URLSearchParams({ title: c.title, city: c.city, lat: c.lat || '', lng: c.lng || '', id: p.id || '' })).catch(() => ({ similar: [] }));\n    $('#dup', d).innerHTML = r.similar.length ? `<div class=\"warn\">انتبه، يمكن المكان موجود: ${r.similar.map((x) => `<a href=\"#\" data-sim=\"${x.id}\">${h(x.title)}</a> (${cityName(x.city)} · ${x.why} · ${ST[x.status][0]})`).join('، ')}</div>` : '';\n    $('#dup', d).querySelectorAll('[data-sim]').forEach((a) => (a.onclick = async (e) => { e.preventDefault(); if (confirm('تفتح المكان الموجود؟ التعديلات اللي هنا ما تنحفظ.')) editPlace((await api('/admin/places/' + a.dataset.sim)).place); }));\n  }, 500); };\n  $('#title', d).addEventListener('change', checkDup); $('#city', d).addEventListener('change', checkDup);\n  imagesWidget($('#imgs', d), images, drawPrev);\n  chipsWidget($('#cats', d), META.placeCats, cats, true);\n  const kEl = $('#kinds', d);\n  const drawK = () => { kEl.innerHTML = `<div class=\"chips\">${META.kinds.map((k) => `<span class=\"chip ${kinds.includes(k) ? 'on' : ''}\" data-k=\"${k}\">${KIND[k]}</span>`).join('')}</div>`; kEl.querySelectorAll('.chip').forEach((c) => (c.onclick = () => { const i = kinds.indexOf(c.dataset.k); i >= 0 ? kinds.splice(i, 1) : kinds.push(c.dataset.k); drawK(); drawPrev(); })); };\n  drawK();\n  geoWidget($('#geoBox', d), p.lat, p.lng, () => $('#city', d).value, $('#address', d), () => { if (isNew) checkDup(); drawPrev(); });\n  $('#x', d).onclick = closeDrawer;\n  function collect() { const g = parseGeo($('#geo', d)?.value || ''); return { title: $('#title', d).value, title_en: $('#title_en', d).value, city: $('#city', d).value, cats, kinds, images, summary: $('#summary', d).value, body: $('#body', d).value, lat: g?.[0] ?? null, lng: g?.[1] ?? null, address: $('#address', d).value, phone: $('#phone', d).value, website: $('#website', d).value }; }\n  const save = async (status) => {\n    try {\n      const r = await api(isNew ? '/admin/places' : '/admin/places/' + p.id, { method: isNew ? 'POST' : 'PUT', body: collect() });\n      if (status) await api(`/admin/places/${r.place.id}/status`, { method: 'POST', body: { status } });\n      toast(status === 'live' ? 'انحفظ وانتشر' : status === 'draft' ? 'رجع مسودة' : 'انحفظ'); closeDrawer(); VIEW === 'places' ? loadPlaces() : render();\n    } catch (e) { toast(errMsg(e)); }\n  };\n  $('#save', d).onclick = () => save();\n  $('#pub', d) && ($('#pub', d).onclick = () => save('live'));\n  $('#unpub', d) && ($('#unpub', d).onclick = () => save('draft'));\n  $('#hide', d) && ($('#hide', d).onclick = async () => { if (!confirm('تخفي المكان من التطبيق؟ تقدر ترجعه بعدين.')) return; await api(`/admin/places/${p.id}/status`, { method: 'POST', body: { status: 'hidden' } }); toast('انخفى'); closeDrawer(); VIEW === 'places' ? loadPlaces() : render(); });\n}\n\n/* ——— الفعاليات ——— */\nconst EF = { when: 'upcoming', status: '', city: '', q: '' };\n// التاريخ يندخل بتوقيت مكة، وينحفظ UTC\nconst toLocal = (iso) => { if (!iso) return ''; const d = new Date(new Date(iso).getTime() + 3 * 3600e3); return d.toISOString().slice(0, 16); };\nconst fromLocal = (v) => (v ? new Date(v + ':00+03:00').toISOString() : '');\nconst fmt = (iso) => { if (!iso) return ''; return new Date(iso).toLocaleString('ar-SA-u-ca-gregory-nu-latn', { timeZone: 'Asia/Riyadh', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' }); };\nasync function eventsView() {\n  const m = $('#main');\n  m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>الفعاليات</h1><p class=\"sub\">الفعالية الجديدة تنحفظ مسودة. اربطها بموسم من التصنيفات عشان تطلع في صفحة الموسم.</p></div><button class=\"btn o\" id=\"add\">+ فعالية جديدة</button></div>\n    <div class=\"tabs\">${[['upcoming', 'القادمة'], ['past', 'السابقة'], ['all', 'الكل']].map(([k, t]) => `<button data-w=\"${k}\" class=\"${EF.when === k ? 'on' : ''}\">${t}</button>`).join('')}</div>\n    <div class=\"filters\"><input class=\"in\" id=\"q\" placeholder=\"ابحث بالاسم أو التصنيف\" value=\"${h(EF.q)}\">\n    <select class=\"in\" id=\"city\"><option value=\"\">كل المدن</option>${META.cities.map((c) => `<option value=\"${c.id}\" ${EF.city === c.id ? 'selected' : ''}>${c.name}</option>`).join('')}</select>\n    <select class=\"in\" id=\"status\"><option value=\"\">كل الحالات</option>${Object.entries(ST).map(([k, v]) => `<option value=\"${k}\" ${EF.status === k ? 'selected' : ''}>${v[0]}</option>`).join('')}</select></div>\n    <div id=\"res\" class=\"list\"></div>`;\n  $('#add').onclick = () => editEvent(null);\n  m.querySelectorAll('[data-w]').forEach((b) => (b.onclick = () => { EF.when = b.dataset.w; eventsView(); }));\n  let t; $('#q').oninput = (e) => { clearTimeout(t); t = setTimeout(() => { EF.q = e.target.value; loadEvents(); }, 350); };\n  ['city', 'status'].forEach((k) => ($('#' + k).onchange = (e) => { EF[k] = e.target.value; loadEvents(); }));\n  loadEvents();\n}\nasync function loadEvents() {\n  const d = await api('/admin/events?' + new URLSearchParams(Object.entries(EF).filter(([, v]) => v)));\n  $('#res').innerHTML = d.events.map((e) => `<div class=\"item\" data-id=\"${e.id}\">${e.thumb ? `<img src=\"${h(e.thumb)}\" loading=\"lazy\">` : '<div class=\"ph\">بدون صورة</div>'}\n    <div class=\"grow\"><div class=\"t\">${h(e.title)}</div><div class=\"m\">${fmt(e.start)}${e.end ? ' ← ' + fmt(e.end) : ''} · ${cityName(e.city)}</div><div class=\"m\">${e.cats.map(h).join('، ')}</div></div>\n    <span class=\"badge ${ST[e.status][1]}\">${ST[e.status][0]}</span></div>`).join('') || '<div class=\"empty\">ما فيه فعاليات</div>';\n  document.querySelectorAll('#res .item').forEach((el) => (el.onclick = async () => editEvent((await api('/admin/events/' + el.dataset.id)).event)));\n}\nfunction editEvent(e) {\n  const isNew = !e;\n  e = e || { title: '', summary: '', body: '', images: [], start: '', end: '', all_day: false, cats: [], city: '', lat: null, lng: null, address: '', tickets: '', link: '', status: 'draft' };\n  const images = [...e.images], cats = [...e.cats];\n  const d = drawer(`<div class=\"row\"><div class=\"grow\"><h2>${isNew ? 'فعالية جديدة' : h(e.title)}</h2><div class=\"m muted\">${isNew ? 'بتنحفظ مسودة' : `رقم ${e.id} · <span class=\"badge ${ST[e.status][1]}\">${ST[e.status][0]}</span>`}</div></div><button class=\"btn ghost\" id=\"x\">إغلاق</button></div>\n    <div class=\"f\"><label>اسم الفعالية *</label><input class=\"in\" id=\"title\" value=\"${h(e.title)}\"></div>\n    <div class=\"two\"><div class=\"f\"><label>تبدأ * (بتوقيت مكة)</label><input class=\"in\" type=\"datetime-local\" id=\"start\" value=\"${toLocal(e.start)}\"></div><div class=\"f\"><label>تنتهي</label><input class=\"in\" type=\"datetime-local\" id=\"end\" value=\"${toLocal(e.end)}\"></div></div>\n    <div class=\"f\"><label style=\"display:flex;gap:8px;align-items:center;font-weight:600\"><input type=\"checkbox\" id=\"all_day\" ${e.all_day ? 'checked' : ''}> طول اليوم (بدون ساعة محددة)</label></div>\n    <div class=\"f\"><label>الموسم</label><div id=\"season\"></div><small>الفعاليات اللي تحمل اسم الموسم تطلع في صفحته في التطبيق</small></div>\n    <div class=\"f\"><label>النوع</label><div id=\"cats\"></div></div>\n    <div class=\"f\"><label>الصور</label><div id=\"imgs\"></div></div>\n    <div class=\"f\"><label>وصف قصير</label><input class=\"in\" id=\"summary\" value=\"${h(e.summary)}\" maxlength=\"400\"></div>\n    <div class=\"f\"><label>التفاصيل</label><textarea class=\"in\" id=\"body\">${h(plainBody(e.body))}</textarea></div>\n    <div class=\"two\"><div class=\"f\"><label>المدينة</label><select class=\"in\" id=\"city\"><option value=\"\">تلقائي من الموقع</option>${META.cities.map((c) => `<option value=\"${c.id}\" ${e.city === c.id ? 'selected' : ''}>${c.name}</option>`).join('')}</select></div>\n    <div class=\"f\"><label>المكان (العنوان)</label><input class=\"in\" id=\"address\" value=\"${h(e.address)}\" placeholder=\"بوليفارد سيتي، الرياض\"><small>أول جزء قبل الفاصلة يصير «منطقة الموسم»</small></div></div>\n    <div class=\"f\"><label>الموقع على الخريطة</label><div id=\"geoBox\"></div></div>\n    <div class=\"two\"><div class=\"f\"><label>رابط التذاكر</label><input class=\"in\" id=\"tickets\" dir=\"ltr\" value=\"${h(e.tickets)}\"></div><div class=\"f\"><label>رابط الفعالية</label><input class=\"in\" id=\"link\" dir=\"ltr\" value=\"${h(e.link)}\"></div></div>\n    <div class=\"bar\"><button class=\"btn\" id=\"save\">حفظ</button>${e.status !== 'live' ? '<button class=\"btn g\" id=\"pub\">حفظ وانشر</button>' : '<button class=\"btn ghost\" id=\"unpub\">رجّعها مسودة</button>'}\n      ${!isNew && e.status !== 'hidden' ? '<button class=\"btn ghost\" id=\"hide\" style=\"color:var(--pinkDeep)\">إخفاء</button>' : ''}${!isNew ? '<button class=\"btn ghost\" id=\"dup\">نسخة منها</button>' : ''}</div>`);\n  imagesWidget($('#imgs', d), images);\n  const seasonSel = cats.filter((c) => /^(موسم|لحظات)/.test(c)), typeSel = cats.filter((c) => !/^(موسم|لحظات)/.test(c));\n  chipsWidget($('#season', d), [...new Set([...SEASONS, ...META.eventCats.filter((c) => /^(موسم|لحظات)/.test(c))])], seasonSel, true);\n  chipsWidget($('#cats', d), [...new Set([...EV_TYPES, ...META.eventCats.filter((c) => !/^(موسم|لحظات)/.test(c))])], typeSel, true);\n  geoWidget($('#geoBox', d), e.lat, e.lng, () => $('#city', d).value, $('#address', d));\n  $('#x', d).onclick = closeDrawer;\n  const collect = () => { const g = parseGeo($('#geo', d).value); return { title: $('#title', d).value, start: fromLocal($('#start', d).value), end: fromLocal($('#end', d).value), all_day: $('#all_day', d).checked, cats: [...seasonSel, ...typeSel], images, summary: $('#summary', d).value, body: $('#body', d).value, city: $('#city', d).value, address: $('#address', d).value, lat: g?.[0] ?? null, lng: g?.[1] ?? null, tickets: $('#tickets', d).value, link: $('#link', d).value }; };\n  const save = async (status, asNew) => {\n    try {\n      const r = await api(isNew || asNew ? '/admin/events' : '/admin/events/' + e.id, { method: isNew || asNew ? 'POST' : 'PUT', body: collect() });\n      if (status) await api(`/admin/events/${r.event.id}/status`, { method: 'POST', body: { status } });\n      toast(asNew ? 'انحفظت نسخة جديدة كمسودة' : status === 'live' ? 'انحفظت وانتشرت' : 'انحفظت'); closeDrawer(); VIEW === 'events' ? loadEvents() : render();\n      if (asNew) editEvent(r.event);\n    } catch (er) { toast(errMsg(er)); }\n  };\n  $('#save', d).onclick = () => save();\n  $('#pub', d) && ($('#pub', d).onclick = () => save('live'));\n  $('#unpub', d) && ($('#unpub', d).onclick = () => save('draft'));\n  $('#dup', d) && ($('#dup', d).onclick = () => save(null, true));\n  $('#hide', d) && ($('#hide', d).onclick = async () => { if (!confirm('تخفي الفعالية من التطبيق؟')) return; await api(`/admin/events/${e.id}/status`, { method: 'POST', body: { status: 'hidden' } }); toast('انخفت'); closeDrawer(); VIEW === 'events' ? loadEvents() : render(); });\n}\n\n/* ——— المواسم ——— */\nconst SEASON_COLOR = { 'موسم الرياض': 'var(--purple)', 'موسم جدة': 'var(--skyDeep)', 'موسم الدرعية': 'var(--orangeDeep)', 'لحظات العلا': 'var(--pinkDeep)' };\nasync function seasonsView() {\n  const m = $('#main');\n  m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>المواسم</h1><p class=\"sub\">الموسم يتكوّن من الفعاليات اللي تحمل اسمه. أضف فعالية واختر الموسم، وتطلع تلقائياً في صفحته في التطبيق.</p></div><button class=\"btn o\" id=\"add\">+ فعالية لموسم</button></div><div id=\"res\" class=\"list\"><p class=\"muted\">لحظة...</p></div>`;\n  $('#add').onclick = () => editEvent(null);\n  const d = await api('/admin/seasons');\n  const now = new Date().toISOString();\n  $('#res').innerHTML = d.seasons.map((x) => {\n    const st = x.end < now ? 'انتهى' : x.start > now ? 'يبدأ ' + fmt(x.start) : 'شغّال الحين';\n    return `<div class=\"season\" data-n=\"${h(x.name)}\" style=\"border-right-color:${SEASON_COLOR[x.name] || 'var(--lilac)'}\"><div class=\"row\"><b class=\"grow\" style=\"font-size:18px\">${h(x.name)}</b><span class=\"badge ${x.end < now ? 'b-hidden' : 'b-live'}\">${st}</span></div>\n      <div class=\"m muted\" style=\"margin-top:6px\">${x.live} فعالية منشورة${x.drafts ? ` · ${x.drafts} مسودة` : ''} · من ${fmt(x.start)} إلى ${fmt(x.end)}</div></div>`;\n  }).join('') || '<div class=\"empty\">ما فيه مواسم. أضف فعالية واختر لها موسم.</div>';\n  m.querySelectorAll('[data-n]').forEach((el) => (el.onclick = () => { EF.q = el.dataset.n; EF.when = 'all'; VIEW = 'events'; render(); }));\n}\n\n/* ——— مختارات الأسبوع ——— */\nconst SEAS = { a: 'طول السنة', w: 'الشتاء', s: 'الصيف' };\nasync function weeklyView() {\n  const m = $('#main');\n  m.innerHTML = '<p class=\"muted\">لحظة...</p>';\n  const d = await api('/admin/weekly');\n  const pool = d.pool;\n  const draw = () => {\n    m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>مختارات الأسبوع</h1><p class=\"sub\">قائمة الأماكن اللي يختار منها التطبيق كل أسبوع 5 أماكن من مدن مختلفة. المميّزة ★ تطلع أول. «الشتاء» تطلع من نوفمبر لمارس، و«الصيف» من مايو لسبتمبر.</p></div><button class=\"btn g\" id=\"saveW\">حفظ القائمة</button></div>\n      <div class=\"card\" style=\"margin-bottom:14px\"><b>أضف مكان</b><input class=\"in\" id=\"wq\" placeholder=\"ابحث باسم المكان\" style=\"margin-top:8px\"><div id=\"wres\" class=\"list\" style=\"margin-top:8px\"></div></div>\n      <div class=\"muted\" style=\"font-size:13px;margin-bottom:8px\">${pool.length} مكان في القائمة</div>\n      <div class=\"list\">${pool.map((x, i) => `<div class=\"item\" style=\"cursor:default\">${x.thumb ? `<img src=\"${h(x.thumb)}\" loading=\"lazy\">` : '<div class=\"ph\">بدون صورة</div>'}\n        <div class=\"grow\"><div class=\"t\">${x.x ? '★ ' : ''}${h(x.title)}</div><div class=\"m\">${cityName(x.city)}${x.status !== 'live' ? ' · <span style=\"color:var(--pinkDeep)\">مو منشور</span>' : ''}</div></div>\n        <select class=\"in\" style=\"width:auto\" data-s=\"${i}\">${Object.entries(SEAS).map(([k, v]) => `<option value=\"${k}\" ${x.s === k ? 'selected' : ''}>${v}</option>`).join('')}</select>\n        <button class=\"mini\" style=\"background:var(--softOrange);color:var(--orangeDeep)\" data-x=\"${i}\">${x.x ? 'شيل التمييز' : '★ ميّزه'}</button>\n        <button class=\"mini\" style=\"background:var(--chip);color:var(--pinkDeep)\" data-r=\"${i}\">شيل</button></div>`).join('')}</div>`;\n    m.querySelectorAll('[data-s]').forEach((el) => (el.onchange = () => { pool[+el.dataset.s].s = el.value; }));\n    m.querySelectorAll('[data-x]').forEach((el) => (el.onclick = () => { const x = pool[+el.dataset.x]; x.x ? delete x.x : (x.x = 1); draw(); }));\n    m.querySelectorAll('[data-r]').forEach((el) => (el.onclick = () => { pool.splice(+el.dataset.r, 1); draw(); }));\n    $('#saveW').onclick = async () => { await api('/admin/weekly', { method: 'POST', body: { pool: pool.map(({ id, s, x }) => (x ? { id, s, x: 1 } : { id, s })) } }); toast('انحفظت القائمة'); };\n    let t; $('#wq').oninput = (e) => { clearTimeout(t); t = setTimeout(async () => {\n      const v = e.target.value.trim(); if (v.length < 2) { $('#wres').innerHTML = ''; return; }\n      const r = await api('/admin/places?status=live&q=' + encodeURIComponent(v));\n      $('#wres').innerHTML = r.places.slice(0, 6).map((p) => `<div class=\"item\" data-add=\"${p.id}\" data-t=\"${h(p.title)}\" data-c=\"${p.city}\" data-th=\"${h(p.thumb)}\"><div class=\"grow\"><div class=\"t\">${h(p.title)}</div><div class=\"m\">${cityName(p.city)}</div></div>${pool.some((x) => x.id === p.id) ? '<span class=\"badge b-live\">موجود</span>' : '<span class=\"mini\" style=\"background:var(--purple);color:#fff\">+ أضف</span>'}</div>`).join('') || '<div class=\"muted\">ما لقيت</div>';\n      $('#wres').querySelectorAll('[data-add]').forEach((el) => (el.onclick = () => { const id = +el.dataset.add; if (pool.some((x) => x.id === id)) return; pool.unshift({ id, s: 'a', title: el.dataset.t, city: el.dataset.c, thumb: el.dataset.th, status: 'live' }); draw(); toast('انضاف — اضغط «حفظ القائمة»'); }));\n    }, 350); };\n  };\n  draw();\n}\n\n/* ——— الأخبار والمقالات ——— */\nasync function articlesView() {\n  const m = $('#main');\n  m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>الأخبار والمقالات</h1><p class=\"sub\">آخر 3 أخبار تطلع في الصفحة الرئيسية للتطبيق. الجديد ينحفظ مسودة.</p></div><button class=\"btn o\" id=\"add\">+ خبر جديد</button></div><div id=\"res\" class=\"list\"><p class=\"muted\">لحظة...</p></div>`;\n  $('#add').onclick = () => editArticle(null);\n  const d = await api('/admin/articles');\n  $('#res').innerHTML = d.articles.map((a) => `<div class=\"item\" data-id=\"${a.id}\">${a.thumb ? `<img src=\"${h(a.thumb)}\" loading=\"lazy\">` : '<div class=\"ph\">بدون صورة</div>'}\n    <div class=\"grow\"><div class=\"t\">${h(a.title)}</div><div class=\"m\">${fmt(a.date)}${a.author ? ' · ' + h(a.author) : ''}</div></div><span class=\"badge ${ST[a.status][1]}\">${ST[a.status][0]}</span></div>`).join('') || '<div class=\"empty\">ما فيه أخبار</div>';\n  m.querySelectorAll('[data-id]').forEach((el) => (el.onclick = async () => editArticle((await api('/admin/articles/' + el.dataset.id)).article)));\n}\nfunction editArticle(a) {\n  const isNew = !a;\n  a = a || { title: '', author: 'فريق دليل السعودية', date: new Date().toISOString(), summary: '', body: '', images: [], cats: [], status: 'draft' };\n  const images = [...a.images];\n  const d = drawer(`<div class=\"row\"><div class=\"grow\"><h2>${isNew ? 'خبر جديد' : h(a.title)}</h2><div class=\"m muted\">${isNew ? 'بينحفظ مسودة' : `<span class=\"badge ${ST[a.status][1]}\">${ST[a.status][0]}</span>`}</div></div><button class=\"btn ghost\" id=\"x\">إغلاق</button></div>\n    <div class=\"f\"><label>العنوان *</label><input class=\"in\" id=\"title\" value=\"${h(a.title)}\"></div>\n    <div class=\"two\"><div class=\"f\"><label>الكاتب</label><input class=\"in\" id=\"author\" value=\"${h(a.author)}\"></div><div class=\"f\"><label>التاريخ</label><input class=\"in\" type=\"datetime-local\" id=\"date\" value=\"${toLocal(a.date)}\"></div></div>\n    <div class=\"f\"><label>الصور</label><div id=\"imgs\"></div></div>\n    <div class=\"f\"><label>ملخص</label><input class=\"in\" id=\"summary\" value=\"${h(a.summary)}\" maxlength=\"400\"></div>\n    <div class=\"f\"><label>النص</label><textarea class=\"in\" id=\"body\" style=\"min-height:260px\">${h(plainBody(a.body))}</textarea><small>سطر فاضي بين الفقرات</small></div>\n    <div class=\"bar\"><button class=\"btn\" id=\"save\">حفظ</button>${a.status !== 'live' ? '<button class=\"btn g\" id=\"pub\">حفظ وانشر</button>' : '<button class=\"btn ghost\" id=\"unpub\">رجّعه مسودة</button>'}${!isNew && a.status !== 'hidden' ? '<button class=\"btn ghost\" id=\"hide\" style=\"color:var(--pinkDeep)\">إخفاء</button>' : ''}</div>`);\n  imagesWidget($('#imgs', d), images);\n  $('#x', d).onclick = closeDrawer;\n  const save = async (status) => {\n    try {\n      const body = { title: $('#title', d).value, author: $('#author', d).value, date: fromLocal($('#date', d).value), summary: $('#summary', d).value, body: $('#body', d).value, images };\n      const r = await api(isNew ? '/admin/articles' : '/admin/articles/' + a.id, { method: isNew ? 'POST' : 'PUT', body });\n      if (status) await api(`/admin/articles/${r.article.id}/status`, { method: 'POST', body: { status } });\n      toast(status === 'live' ? 'انحفظ وانتشر' : 'انحفظ'); closeDrawer(); VIEW === 'articles' ? articlesView() : render();\n    } catch (e) { toast(errMsg(e)); }\n  };\n  $('#save', d).onclick = () => save();\n  $('#pub', d) && ($('#pub', d).onclick = () => save('live'));\n  $('#unpub', d) && ($('#unpub', d).onclick = () => save('draft'));\n  $('#hide', d) && ($('#hide', d).onclick = async () => { if (!confirm('تخفي الخبر؟')) return; await api(`/admin/articles/${a.id}/status`, { method: 'POST', body: { status: 'hidden' } }); toast('انخفى'); closeDrawer(); articlesView(); });\n}\n\n/* ——— المجتمع ——— */\nlet CTAB = 'reported';\nasync function communityView() {\n  const m = $('#main');\n  m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>المجتمع</h1><p class=\"sub\">راجع البلاغات وكل المشاركات، وأرسل رسالة للمستخدمين تنزل في إشعارات التطبيق.</p></div><div class=\"row\"><button class=\"btn\" id=\"chBtn\">تحدي الأسبوع</button><button class=\"btn o\" id=\"msgBtn\">رسالة للمستخدمين</button></div></div>\n    <div class=\"tabs\">${[['reported', 'البلاغات'], ['all', 'كل المشاركات']].map(([k, t]) => `<button data-c=\"${k}\" class=\"${CTAB === k ? 'on' : ''}\">${t}</button>`).join('')}</div><div id=\"res\" class=\"list\"><p class=\"muted\">لحظة...</p></div>`;\n  m.querySelectorAll('[data-c]').forEach((b) => (b.onclick = () => { CTAB = b.dataset.c; communityView(); }));\n  $('#msgBtn').onclick = () => {\n    const d = drawer(`<div class=\"row\"><h2 class=\"grow\">رسالة للمستخدمين</h2><button class=\"btn ghost\" id=\"x\">إغلاق</button></div>\n      <div class=\"f\"><label>الرسالة (140 حرف)</label><textarea class=\"in\" id=\"t\" maxlength=\"140\" style=\"min-height:90px\" placeholder=\"مثلاً: موسم الرياض بدأ! شوف الفعاليات في الدليل\"></textarea></div>\n      <div class=\"f\"><label>لمين؟</label><select class=\"in\" id=\"c\"><option value=\"\">كل المستخدمين</option>${META.cities.map((c) => `<option value=\"${c.id}\">متابعين ${c.name}</option>`).join('')}</select></div>\n      <div class=\"hint\" style=\"margin-top:12px\">تنزل في صفحة الإشعارات داخل التطبيق. إشعارات الجوال (اللي تطلع على الشاشة) تتفعّل في النسخة الجاية.</div>\n      <div class=\"bar\"><button class=\"btn o\" id=\"send\">أرسل</button></div>`);\n    $('#x', d).onclick = closeDrawer;\n    $('#send', d).onclick = async () => {\n      const text = $('#t', d).value.trim(); if (text.length < 4) return toast('اكتب الرسالة');\n      if (!confirm('ترسلها الحين؟')) return;\n      try { const r = await api('/admin/notify', { method: 'POST', body: { text, city: $('#c', d).value } }); toast(`انرسلت لـ ${r.sent} مستخدم`); closeDrawer(); } catch (e) { toast(errMsg(e)); }\n    };\n  };\n  $('#chBtn').onclick = async () => {\n    const cur = (await api('/admin/challenge')).challenge || {};\n    const imgs = cur.photo ? [cur.photo] : [];\n    const d = drawer(`<div class=\"row\"><h2 class=\"grow\">تحدي الأسبوع</h2><button class=\"btn ghost\" id=\"x\">إغلاق</button></div>\n      <p class=\"muted\">يطلع بطاقة برتقالية فوق المجتمع. اللي يشارك يضغطها ويكتب مشاركته، وتنحسب المشاركات اللي فيها الوسم.</p>\n      <div class=\"f\"><label>عنوان التحدي</label><input class=\"in\" id=\"title\" value=\"${h(cur.title || '')}\" placeholder=\"صوّر غروب كورنيش جدة\"></div>\n      <div class=\"f\"><label>الجائزة</label><input class=\"in\" id=\"prize\" value=\"${h(cur.prize || '')}\" placeholder=\"وسم «عدسة الدليل» + كوبون\"></div>\n      <div class=\"two\"><div class=\"f\"><label>الوسم (بدون #)</label><input class=\"in\" id=\"tag\" value=\"${h(cur.tag || '')}\" placeholder=\"غروب_جدة\"></div><div class=\"f\"><label>ينتهي</label><input class=\"in\" type=\"datetime-local\" id=\"end\" value=\"${toLocal(cur.end)}\"></div></div>\n      <div class=\"f\"><label>صورة البطاقة</label><div id=\"imgs\"></div></div>\n      <div class=\"bar\"><button class=\"btn g\" id=\"save\">حفظ وانشر</button>${cur.title ? '<button class=\"btn ghost\" id=\"stop\" style=\"color:var(--pinkDeep)\">أوقف التحدي</button>' : ''}</div>`);\n    imagesWidget($('#imgs', d), imgs);\n    $('#x', d).onclick = closeDrawer;\n    $('#save', d).onclick = async () => { await api('/admin/challenge', { method: 'POST', body: { title: $('#title', d).value, prize: $('#prize', d).value, tag: $('#tag', d).value.replace(/^#/, ''), end: fromLocal($('#end', d).value), photo: imgs[0] || '' } }); toast('انحفظ التحدي'); closeDrawer(); };\n    $('#stop', d) && ($('#stop', d).onclick = async () => { await api('/admin/challenge', { method: 'POST', body: { clear: true } }); toast('وقف التحدي'); closeDrawer(); });\n  };\n  const why = { reports: 'انخفت بالبلاغات', owner: 'صاحبها حذفها', admin: 'أنت أخفيتها', account: 'الحساب انحذف' };\n  let rows;\n  if (CTAB === 'reported') {\n    const d = await api('/admin/community/reported');\n    rows = [...d.posts.map((x) => ({ ...x, t: 'p' })), ...d.answers.map((x) => ({ ...x, t: 'a' }))];\n  } else {\n    rows = (await api('/admin/community/posts')).posts.map((x) => ({ ...x, t: 'p' }));\n  }\n  const KN = { question: 'سؤال', tip: 'نصيحة', photo: 'صورة' };\n  $('#res').innerHTML = rows.map((x) => `<div class=\"post\"><div class=\"row\"><span class=\"tag\">${x.t === 'p' ? (KN[x.kind] || 'مشاركة') : 'إجابة'} #${x.id}</span>${x.name ? `<b style=\"font-size:13px\">${h(x.name)}</b>` : ''}<span class=\"badge ${x.status === 'visible' ? 'b-live' : 'b-hidden'}\">${x.status === 'visible' ? 'ظاهرة' : 'مخفية'}</span><span class=\"muted\" style=\"font-size:13px\">${x.reports ? x.reports + ' بلاغ' : ''}${x.hidden_by ? ' · ' + (why[x.hidden_by] || '') : ''}${x.answers != null ? ` · ${x.answers} إجابة · ${x.thanks} شكر` : ''}</span></div>\n    ${x.photo ? `<img src=\"${h(x.photo)}\" style=\"max-width:260px;border-radius:14px\">` : ''}<div>${h(x.text)}</div><div class=\"row\">${x.status === 'visible' ? `<button class=\"btn p\" data-t=\"${x.t}\" data-id=\"${x.id}\" data-h=\"1\">إخفاء</button>` : `<button class=\"btn g\" data-t=\"${x.t}\" data-id=\"${x.id}\" data-h=\"0\">أظهرها</button>`}</div></div>`).join('') || `<div class=\"empty\">${CTAB === 'reported' ? 'ما فيه بلاغات. المجتمع نظيف' : 'ما فيه مشاركات للحين'}</div>`;\n  m.querySelectorAll('[data-t]').forEach((b) => (b.onclick = async () => { await api('/admin/community/moderate', { method: 'POST', body: { target: b.dataset.t, id: +b.dataset.id, hidden: b.dataset.h === '1' } }); toast('تم'); communityView(); }));\n}\n\n/* ——— المستخدمين ——— */\nasync function usersView(q = '') {\n  const m = $('#main');\n  if (!$('#uq')) m.innerHTML = `<h1>المستخدمين</h1><p class=\"sub\">«مرشد موثّق» يطلع جنب اسمه في المجتمع. «فريق الدليل» للإدارة.</p><div class=\"filters\"><input class=\"in\" id=\"uq\" placeholder=\"ابحث بالاسم\"></div><div id=\"res\" class=\"list\"></div>`;\n  let t; $('#uq').oninput = (e) => { clearTimeout(t); t = setTimeout(() => usersView(e.target.value), 350); };\n  const d = await api('/admin/users' + (q ? '?q=' + encodeURIComponent(q) : ''));\n  const R = { user: 'مستخدم', guide: 'مرشد موثّق', admin: 'فريق الدليل' };\n  $('#res').innerHTML = d.users.map((u) => `<div class=\"item\" style=\"cursor:default\"><div class=\"ph\" style=\"border-radius:50%;background:var(--lilac);color:#fff;font-weight:700;font-size:20px\">${h((u.name || 'د')[0])}</div>\n    <div class=\"grow\"><div class=\"t\">${h(u.name || 'بدون اسم')}</div><div class=\"m\">${u.points} نقطة · ${cityName(u.city)} · سجّل ${new Date(u.created * 1000).toLocaleDateString('ar-SA-u-ca-gregory-nu-latn')}</div></div>\n    <select class=\"in\" style=\"width:auto\" data-u=\"${u.id}\">${Object.entries(R).map(([k, v]) => `<option value=\"${k}\" ${u.role === k ? 'selected' : ''}>${v}</option>`).join('')}</select></div>`).join('') || '<div class=\"empty\">ما فيه مستخدمين</div>';\n  m.querySelectorAll('select[data-u]').forEach((s) => (s.onchange = async () => { await api('/admin/community/role', { method: 'POST', body: { userId: s.dataset.u, role: s.value } }); toast('تغيّرت الصلاحية'); }));\n}\n\nrender();\n</script>\n</body>\n</html>\n";
